#
# In the worker logs, the metrics.jsonl content appears as stdout in tool_result,
# but it's escaped multiple times as JSON strings.
#
# Strategy: Find lines with tool_result content, unescape the stdout, then
# parse each metrics line individually.

def unescape_json_string(s, max_depth=10):
    """Recursively unescape a JSON string value."""
    for _ in range(max_depth):
        try:
            result = json.loads('"' + s + '"') if not s.startswith('"') else json.loads(s)
            if isinstance(result, str) and result != s:
                s = result
                continue
            return result
        except:
            try:
                result = json.loads(s)
                if isinstance(result, str) and result != s:
                    s = result
                    continue
                return result
            except:
                return s
    return s

def extract_metrics_from_stdout(stdout_text):
    """Parse metrics from a stdout text that contains metrics.jsonl lines."""
    results = []
    # Split by newlines (both escaped and real)
    lines = re.split(r'(?:\\n|\n)', stdout_text)
    for line in lines:
        line = line.strip()
        if not line or 'actor_loss' not in line:
            continue
        # Try to parse as JSON
        try:
            obj = json.loads(line)
            if isinstance(obj, dict) and 'step' in obj and 'actor_loss' in obj:
                # Verify it's an eval checkpoint by checking for model_loss or value_loss
                if 'model_loss' in obj or 'value_loss' in obj or 'train_return' in obj:
                    results.append({
                        'step': int(obj['step']),
                        'actor_loss': float(obj['actor_loss'])
                    })
        except:
            pass
    return results

def deep_extract_stdout(obj):
    """Recursively find stdout strings in a nested JSON object."""
    stdouts = []
    if isinstance(obj, dict):
        if 'stdout' in obj and isinstance(obj['stdout'], str):
            stdouts.append(obj['stdout'])
        for v in obj.values():
            stdouts.extend(deep_extract_stdout(v))
    elif isinstance(obj, list):
        for item in obj:
            stdouts.extend(deep_extract_stdout(item))
    elif isinstance(obj, str):
        # Try to parse as JSON and recurse
        try:
            parsed = json.loads(obj)
            if parsed != obj:
                stdouts.extend(deep_extract_stdout(parsed))
        except:
            pass
    return stdouts

