import json, re, sys, os

def recursive_unescape(s, depth=0, max_depth=10):
    """Recursively unescape JSON strings."""
    if depth >= max_depth or not isinstance(s, str):
        return s
    try:
        parsed = json.loads(s)
        if isinstance(parsed, str):
            return recursive_unescape(parsed, depth+1, max_depth)
        return parsed
    except:
        return s

def extract_metrics_lines(text):
    """Given a text (possibly containing \\n-separated JSON lines), extract metrics entries with actor_loss."""
    results = []
    # Split by both literal \n and actual newlines
    for sep in ['\\n', '\n']:
        parts = text.split(sep)
        for part in parts:
            part = part.strip()
            if not part or 'actor_loss' not in part:
                continue
            try:
                obj = json.loads(part)
                if isinstance(obj, dict) and 'step' in obj and 'actor_loss' in obj:
                    # Must be a training metrics line (has model_loss or value_loss)
                    if 'model_loss' in obj or 'value_loss' in obj:
                        results.append((int(obj['step']), float(obj['actor_loss'])))
            except:
                pass
    return results

def find_stdout_and_extract(obj, results):
    """Recursively navigate JSON to find stdout fields, then extract metrics."""
    if isinstance(obj, dict):
        if 'stdout' in obj and isinstance(obj['stdout'], str):
            pairs = extract_metrics_lines(obj['stdout'])
            results.extend(pairs)
        # Also check 'data' which may contain nested result
        for key, val in obj.items():
            find_stdout_and_extract(val, results)
    elif isinstance(obj, list):
        for item in obj:
            find_stdout_and_extract(item, results)
    elif isinstance(obj, str):
        # Try to parse and recurse
        parsed = recursive_unescape(obj)
        if parsed != obj and not isinstance(parsed, str):
            find_stdout_and_extract(parsed, results)

