import json, re, os

def recursive_unescape(s, depth=0, max_depth=15):
    if depth >= max_depth or not isinstance(s, str):
        return s
    try:
        parsed = json.loads(s)
        if isinstance(parsed, str):
            return recursive_unescape(parsed, depth+1, max_depth)
        return parsed
    except:
        return s

def extract_metrics_from_stdout(stdout_text):
    results = []
    for line in re.split(r'(?:\\\\n|\\n|\n)', stdout_text):
        line = line.strip()
        if not line or 'actor_loss' not in line:
            continue
        try:
            obj = json.loads(line)
            if isinstance(obj, dict) and 'step' in obj and 'actor_loss' in obj and ('model_loss' in obj or 'value_loss' in obj):
                results.append((int(obj['step']), float(obj['actor_loss'])))
        except:
            pass
    return list(set(results))

def find_all_stdouts(obj, depth=0):
    results = []
    if isinstance(obj, dict):
        if 'stdout' in obj and isinstance(obj['stdout'], str):
            results.append(obj['stdout'])
        for v in obj.values():
            results.extend(find_all_stdouts(v, depth+1))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(find_all_stdouts(item, depth+1))
    elif isinstance(obj, str) and depth < 10:
        parsed = recursive_unescape(obj)
        if parsed != obj and not isinstance(parsed, str):
            results.extend(find_all_stdouts(parsed, depth+1))
    return results

# Search ALL log files, but only match on SSH commands that read specific experiment dirs
target_exps = {
    'exp_008d_subsample_on_h8': set(),
    'exp_009b_008d_walker_s2': set(),
    'exp_009e_008d_walker_s1': set(),
}

all_files = [f for f in os.listdir('.') if f.endswith('.log')]

for fname in sorted(all_files):
    try:
        with open(fname) as f:
            lines = [l.strip() for l in f.readlines()]
    except:
        continue

    # Build a map of tool_use_id -> experiment name from SSH commands
    tool_exp_map = {}
    for i, line in enumerate(lines):
        try:
            obj = json.loads(line)
        except:
            continue

        if obj.get('type') == 'assistant':
            msg = obj.get('message', {})
            for c in msg.get('content', []):
                if c.get('type') == 'tool_use':
                    inp = c.get('input', {})
                    cmd = inp.get('command', inp.get('cmd', ''))
                    if cmd:
                        for target_exp in target_exps:
                            if target_exp in cmd:
                                tool_exp_map[c['id']] = target_exp

    # Now find tool_results that correspond to target experiments
    for i, line in enumerate(lines):
        if 'actor_loss' not in line:
            continue
        try:
            obj = json.loads(line)
        except:
            continue

        if obj.get('type') != 'user':
            continue

        msg = obj.get('message', {})
        content = msg.get('content', [])

        for c in content:
            if c.get('type') != 'tool_result':
                continue

            tool_use_id = c.get('tool_use_id', '')
            exp_name = tool_exp_map.get(tool_use_id)

            if not exp_name:
                continue

            tcontent = c.get('content', '')
            if isinstance(tcontent, str) and 'actor_loss' in tcontent:
                parsed = recursive_unescape(tcontent)
                if not isinstance(parsed, str):
                    stdouts = find_all_stdouts(parsed)
                    for stdout in stdouts:
                        pairs = extract_metrics_from_stdout(stdout)
                        if pairs:
                            target_exps[exp_name].update(pairs)

# Print results
for exp_name in sorted(target_exps.keys()):
    pairs = sorted(target_exps[exp_name])
    print(f"\n=== {exp_name} ({len(pairs)} checkpoints) ===")
    for step, al in pairs:
        print(f"  step={step}, actor_loss={al}")

